function normProfile(v) {
    return String(v ?? '').toLowerCase().trim();
}

function isFronius(v) {
    return normProfile(v).includes('fronius');
}

function isSigenergy(v) {
    const p = normProfile(v);
    return p.includes('sigenergy') || p === 'sig' || p === 'sigen';
}

function gNum(name, def = 0) {
    const v = Number(global.get(name));
    return Number.isFinite(v) ? v : def;
}

function gMaybeNum(name) {
    const v = Number(global.get(name));
    return Number.isFinite(v) ? v : null;
}

function toWFromKw(v) {
    const n = Number(v);
    return Number.isFinite(n) ? Math.round(n * 1000) : null;
}

let installed = Number(msg.installed_inverters);
if (!Number.isFinite(installed)) {
    installed = parseInt(String(msg.installed_inverters || '1'), 10);
}
if (!Number.isFinite(installed)) installed = 1;
installed = Math.max(1, Math.min(4, installed));

const profile = 'sigenergy';

/* -------------------- SIGENERGY PATH -------------------- */
if (isSigenergy(profile)) {
    const sig = global.get('sig_state') || {};

    const siteSoc = Number(sig.battery_soc_pct);
    const rawBatteryW = toWFromKw(sig.battery_power_kw);
    const batteryW = rawBatteryW !== null ? -rawBatteryW : null;
    const pvW = toWFromKw(sig.site_pv_power_kw);
    const loadW = toWFromKw(sig.site_load_power_kw);
    const gridW = toWFromKw(sig.site_grid_power_kw);

    const finalSoc = Number.isFinite(siteSoc) ? +siteSoc.toFixed(2) : null;
    const finalBatteryW = batteryW !== null ? batteryW : 0;
    const finalPvW = pvW !== null ? pvW : 0;
    const finalLoadW = loadW;
    const finalGridW = gridW;

    flow.set('site_battery_soc', finalSoc);
    flow.set('site_battery_power_w', finalBatteryW);
    flow.set('site_pv_power_w', finalPvW);
    flow.set('site_load_power_w', finalLoadW);
    flow.set('site_grid_power_w', finalGridW);

    global.set('site_battery_soc', finalSoc);
    global.set('site_battery_power_w', finalBatteryW);
    global.set('site_pv_power_w', finalPvW);
    global.set('site_load_power_w', finalLoadW);
    global.set('site_grid_power_w', finalGridW);

    const attrs = {
        installed_inverters: 1,
        inverter_profile: profile,
        included_inverters: [1],
        included_details: [
            {
                inverter: 1,
                source: 'global.sig_state',
                battery_soc_pct: finalSoc,
                battery_power_w: finalBatteryW,
                pv_power_w: finalPvW,
                load_power_w: finalLoadW,
                grid_power_w: finalGridW,
                last_update: sig.last_update || null
