    node.status({
        fill: 'green',
        shape: 'dot',
        text: `SIG | SOC ${finalSoc ?? 'n/a'}% | Batt ${finalBatteryW}W | PV ${finalPvW}W | Grid ${finalGridW ?? 'n/a'}W | Load ${finalLoadW ?? 'n/a'}W`
